<!doctype html>
<html lang="id" x-data="simsApp()" :class="dark ? 'dark' : ''" x-init="init()">
<head>
  <meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta name="theme-color" content="#0d1830">
  <title>SIMS — Sistem Informasi Manajemen Sekolah</title>
  <meta name="description" content="Template interaktif sistem informasi manajemen sekolah dengan Tailwind CSS, Alpine.js dan SPA routing.">
  <link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">

  @vite(['resources/css/app.css','resources/js/app.js'])
</head>
<body>
<div class="app-frame min-h-screen" x-on:keydown.window="onKeydown($event)" x-on:sims-open-form.window="openEntityModal($event.detail.key,$event.detail.row)" x-on:sims-open-simple.window="openSimpleModal($event.detail.title,$event.detail.label,$event.detail.placeholder)">
  <div class="app-loading-overlay" x-show="isLoading" x-cloak role="status" aria-live="polite" aria-label="Memproses data">
    <div class="app-loading-card"><div class="app-loading-spinner"></div><strong x-text="loadingMessage"></strong><p>Mohon tunggu sebentar.</p></div>
  </div>
  <!-- mobile overlay -->
  <div class="mobile-scrim" x-show="sidebarMobile" x-cloak x-on:click="sidebarMobile=false"></div>
  <aside class="sidebar" :class="{'sidebar-mini':collapsed,'sidebar-mobile-open':sidebarMobile}" aria-label="Navigasi utama">
    <div class="sidebar-logo"><div class="logo-symbol"><svg width="27" height="27" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="m2 9 10-5 10 5-10 5L2 9Z"/><path d="M6 11v5c4 3 8 3 12 0v-5"/><path d="M22 9v6"/></svg></div><div class="logo-copy" x-show="!collapsed"><strong>SIMS<span class="logo-dot">.</span></strong><small>School Management</small></div><button class="sidebar-collapse" aria-label="Perkecil navigasi" x-on:click="collapsed=!collapsed;saveUi()" :title="collapsed?'Perluas sidebar':'Perkecil sidebar'"><span x-html="ico(collapsed?'panel-left-open':'panel-left-close',17)"></span></button></div>
    <div class="school-switch" x-show="!collapsed"><div class="school-mark">S2</div><div class="school-text"><strong>SMPN 2 Konoha</strong><span>Workspace Sekolah</span></div><span x-html="ico('chevrons-up-down',14)"></span></div>
    <nav class="sidebar-scroll" aria-label="Menu utama">
      <template x-for="group in menuGroups" :key="group.label">
        <div class="nav-group"><div class="nav-label" x-show="!collapsed" x-text="group.label"></div>
          <template x-for="item in group.items" :key="item.id"><a href="#" class="nav-link" :class="{'active':route===item.id}" :title="item.title" x-on:click.prevent="navigate(item.id)" :aria-current="route===item.id?'page':null"><span x-html="ico(item.icon,19)"></span><span class="nav-link-text" x-show="!collapsed" x-text="item.title"></span><template x-if="item.badge&&!collapsed"><span class="nav-count" x-text="item.badge"></span></template></a></template>
        </div>
      </template>
    </nav>
    <div class="sidebar-footer"><div class="sidebar-help" x-show="!collapsed"><span x-html="ico('sparkles',17)"></span><strong>Butuh bantuan?</strong><p>Panduan penggunaan SIMS tersedia untuk tim sekolah Anda.</p><button x-on:click="navigate('guide')">Buka panduan <span x-html="ico('arrow-up-right',13)"></span></button></div><a class="nav-link footer-settings" href="#" x-on:click.prevent="navigate('settings')" :class="{'active':route==='settings'}"><span x-html="ico('settings',19)"></span><span x-show="!collapsed">Pengaturan</span></a></div>
  </aside>
  <div class="app-main" :class="{'main-expanded':collapsed}">
    <header class="topbar flex items-center justify-between"><div class="top-left"><button class="icon-btn top-mobile-menu" x-on:click="sidebarMobile=true" aria-label="Buka menu"><span x-html="ico('menu',20)"></span></button><div class="page-ident"><div class="breadcrumb"><span>Workspace</span><span x-html="ico('chevron-right',13)"></span><span x-text="routeTitle"></span></div><div class="heading-line"><h1 x-text="routeTitle"></h1><span class="year-chip" x-on:click="yearMenu=!yearMenu">TA 2026/2027 <span x-html="ico('chevron-down',13)"></span></span><div class="year-dropdown" x-show="yearMenu" x-cloak x-on:click.outside="yearMenu=false"><div x-on:click="yearMenu=false;toast('Tahun ajaran 2026/2027 dipilih','success')">2026/2027 <span x-html="ico('check',14)"></span></div><div x-on:click="yearMenu=false;toast('Data tahun ajaran sebelumnya dalam mode demo','info')">2025/2026</div></div></div></div></div>
      <div class="top-right"><button class="global-search" x-on:click="commandOpen=true;$nextTick(()=> $refs.commandInput?.focus())"><span x-html="ico('search',18)"></span><span>Cari siswa, guru, halaman...</span><kbd>Ctrl K</kbd></button><button class="icon-btn theme-toggle" :title="dark?'Mode terang':'Mode gelap'" x-on:click="dark=!dark;saveUi()"><span x-html="ico(dark?'sun':'moon',19)"></span></button><div class="relative"><button class="icon-btn notification-trigger" x-on:click="notificationsOpen=!notificationsOpen" title="Notifikasi"><span x-html="ico('bell',20)"></span><span class="notif-dot"></span></button><div class="popover notif-popover" x-show="notificationsOpen" x-cloak x-on:click.outside="notificationsOpen=false"><div class="popover-head"><strong>Notifikasi</strong><span class="badge badge-blue">3 baru</span></div><template x-for="n in notices.slice(0,4)" :key="n.title"><button class="notification-item" x-on:click="notificationsOpen=false;navigate('announcements')"><span class="mini-icon blue" x-html="ico(n.icon,16)"></span><span><strong x-text="n.title"></strong><small x-text="n.time"></small></span></button></template><button class="popover-footer" x-on:click="notificationsOpen=false;navigate('announcements')">Lihat semua notifikasi →</button></div></div>
        <div class="relative"><button class="btn btn-primary quick-top" x-on:click="quickMenu=!quickMenu"><span x-html="ico('plus',17)"></span><span>Aksi Cepat</span><span x-html="ico('chevron-down',14)"></span></button><div class="popover quick-popover" x-show="quickMenu" x-cloak x-on:click.outside="quickMenu=false"><template x-for="action in quickActions" :key="action.title"><button x-on:click="quickMenu=false;doQuickAction(action)"><span x-html="ico(action.icon,17)"></span><span x-text="action.title"></span></button></template></div></div>
        <div class="relative"><button class="profile-button" x-on:click="profileOpen=!profileOpen"><span class="profile-avatar">OP</span><span class="profile-text"><strong>Operator Sekolah</strong><small>Administrator</small></span><span x-html="ico('chevron-down',15)"></span></button><div class="popover profile-popover" x-show="profileOpen" x-cloak x-on:click.outside="profileOpen=false"><div class="profile-pop-head"><div class="profile-avatar">OP</div><div><strong>Operator Sekolah</strong><small>operator@sekolah.sch.id</small></div></div><button x-on:click="profileOpen=false;navigate('settings')"><span x-html="ico('settings',16)"></span> Pengaturan akun</button><button x-on:click="profileOpen=false;toast('Halaman profil adalah demo','info')"><span x-html="ico('user',16)"></span> Profil saya</button><button x-on:click="profileOpen=false;toast('Ini hanya template frontend; integrasikan logout Laravel.','warning')"><span x-html="ico('log-out',16)"></span> Keluar</button></div></div>
      </div></header>
    <div class="content-wrap w-full"><div id="page-content" x-html="pageMarkup" aria-live="polite"></div><footer class="main-footer"><span>© 2026 SIMS Design System <span class="footer-dot">•</span> Made for education</span><span>v1.0.0 <span class="footer-dot">•</span> Template & demo data</span></footer></div>
  </div>
  <!-- universal modal -->
  <div class="modal-backdrop" x-show="modal.open" x-cloak x-on:click.self="closeModal()" x-on:keydown.escape.window="closeModal()"><div class="modal-dialog" role="dialog" aria-modal="true" :aria-label="modal.title" x-transition.opacity><div class="modal-header"><div><small x-text="modal.eyebrow || 'SIMS • FORM'" ></small><h3 x-text="modal.title"></h3></div><button class="icon-btn" x-on:click="closeModal()" aria-label="Tutup"><span x-html="ico('x',19)"></span></button></div><div class="modal-body" x-html="modal.body"></div><div class="modal-actions"><button class="btn btn-soft" x-on:click="closeModal()">Batal</button><button class="btn btn-primary" x-on:click="modalSubmit()"><span x-html="ico('check',16)"></span><span x-text="modal.confirm || 'Simpan perubahan'"></span></button></div></div></div>
  <!-- command palette -->
  <div class="command-scrim" x-show="commandOpen" x-cloak x-on:click.self="commandOpen=false" x-on:keydown.escape.window="commandOpen=false"><div class="command-panel" role="dialog" aria-label="Pencarian menu"><div class="command-input"><span x-html="ico('search',21)"></span><input x-ref="commandInput" placeholder="Cari halaman, data, atau tindakan..." x-model="commandQuery" x-on:keydown.enter="selectFirstCommand()"><kbd>ESC</kbd></div><div class="command-results"><small class="command-label">HALAMAN & MENU</small><template x-for="item in filteredCommands" :key="item.id"><button x-on:click="navigate(item.id);commandOpen=false;commandQuery=''" class="command-result"><span x-html="ico(item.icon,18)"></span><span x-text="item.title"></span><span x-html="ico('corner-down-left',14)"></span></button></template><p class="empty-mini" x-show="filteredCommands.length===0">Tidak ada menu yang cocok.</p></div><div class="command-help">Gunakan <kbd>Enter</kbd> untuk memilih <span>·</span> <kbd>Esc</kbd> untuk menutup</div></div></div>
  <!-- toast -->
  <div class="toast-tray" aria-live="polite"><template x-for="t in toasts" :key="t.id"><div class="toast-item" :class="'toast-'+t.type" x-transition><span x-html="ico(t.type==='success'?'check-circle':t.type==='warning'?'alert-triangle':'info',20)"></span><div><strong x-text="t.type==='success'?'Berhasil':t.type==='warning'?'Perhatian':'Informasi'"></strong><p x-text="t.message"></p></div><button x-on:click="toasts=toasts.filter(z=>z.id!==t.id)"><span x-html="ico('x',15)"></span></button></div></template></div>
</div>
</body></html>
